changes.after:
if (msg.type === 'tracker_status') {
    if (msg.chatId !== state.chatId) return;
    const wasBusy = state.busy;
    state.busy = !!msg.busy;
    if (state.busy && !wasBusy) state.busySince = Date.now();
    state.status = msg.status || null;
    render();
    return;
}

if (!S || !Array.isArray(S.arcs)) {
    return h('p', { class: 'rpgc-note' }, 'Saga data is incomplete. Read again to reload it.');
}
